await t("Gallery: safeName saaf naam (../ aur space nahi)", () => { const n = GL.safeName("../../my photo (1).PNG"); return must(/^[a-z0-9]+-[a-z0-9]{4}-[\w.-]+\.png$/.test(n) && !n.includes(".."), n); });
