await t("Catalog: ids unique", () => must(new Set(CAT.CATALOG.map((c) => c.id)).size === CAT.CATALOG.length));
const ALLK = Object.fromEntries(CAT.CATALOG.map((c) => [CAT.keyField(c.id), "k".repeat(32)]));
