await t("OVH models mein gpt-oss-120b", async () => { const ids = await P.listModels({ id: "ovh", base: "https://oai.endpoints.kepler.ai.cloud.ovh.net/v1", key: "" }); return must(ids.includes("gpt-oss-120b")); });
